\begin{equation}
\label{eq:mae}
    \text{MAE} = \frac{1}{N} \sum_{i=1}^{N} \left| \widehat{\text{Acc}}_i^{\text{cal}} - \text{Acc}_i^{\text{clean}} \right|.
