\centering
\small
\begin{tabular}{l r r c r l}
\toprule
\textbf{Domain} & $N_{\text{items}}$ & $\hat{\gamma}$ & \textbf{95\% CI} & \textbf{PPP} & \textbf{Interpretation} \\
\midrule
